import{_ as a,o as t,c as s,a2 as i}from"./chunks/framework.doxMM-x8.js";const f=JSON.parse('{"title":"Existing platform capabilities","description":"","frontmatter":{"docLocale":"en","counterpart":"/guides/platform","contentType":"guide","prev":false,"next":false},"headers":[],"relativePath":"en/guides/platform.md","filePath":"en/guides/platform.md"}'),r={name:"en/guides/platform.md"};function n(o,e,l,p,d,c){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="existing-platform-capabilities" tabindex="-1">Existing platform capabilities <a class="header-anchor" href="#existing-platform-capabilities" aria-label="Permalink to &quot;Existing platform capabilities&quot;">​</a></h1><p>Choose the real interfaces for current Lab Word Platform Core. Start the Node service with <a href="./server-foundation">service foundation</a>. Development needs no Docker, Rust or external database.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:3000/api/v1/auth/session</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:3000/api/openapi.json</span></span></code></pre></div><p>Anonymous session returns 401. OpenAPI returns JSON for migrated endpoints with the title <code>Lab Word Server</code>. See identity, memberships, API keys, audit, idempotency, limits and files in the <a href="./server-platform">platform guide</a>. See byte storage and business references in the <a href="./server-files">file guide</a>. Lab assets, world writes and device programs remain in migration.</p><p>Core does not import Lab. Core owns role management. <a href="https://github.com/CaiZongyuan/labworld/blob/5c8ebb43989a8ddb39a283340ef180887c722544/docs/adr/0008-full-lab-access-for-users-and-agents.md" target="_blank" rel="noreferrer">ADR 0008</a> defines full Lab access for users and valid <code>lab:full</code> Agents. Lab owns its business validator, references and publication callback.</p><p>The generated <a href="./../reference/api">API</a> and <a href="./../reference/config">configuration</a> separate current Node content from the frozen legacy stack. Rust modules, Docker configuration and the complete SDK remain temporarily. They are not runtime dependencies of <code>pnpm dev</code>. Removal follows the complete migration gate. The final switch is still pending.</p><p>Run <code>pnpm test:server</code> from the repository root for real Node HTTP, capabilities and transaction recovery. Frontend tests use MSW at HTTP. They do not prove storage integration. Choose affected interfaces with the <a href="./../testing/feedback-loop">testing guide</a>. Node backups and the complete release path remain in later stages.</p><hr><p>Source version：<code>5c8ebb43989a</code> · <a href="https://github.com/CaiZongyuan/labworld/blob/5c8ebb43989a8ddb39a283340ef180887c722544/docs/guides/platform.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,9)])])}const m=a(r,[["render",n]]);export{f as __pageData,m as default};
